-- ************************************** [consumption].[vw_ContractAnalysis]
CREATE VIEW [consumption].[vw_ContractAnalysis] AS
SELECT 
    cc.CustomerContractId,
    cc.CustomerId,
    c.CustomerName,
    cc.ContractNumber,
    cc.ContractName,
    cc.StartDate,
    cc.EndDate,
    CASE 
        WHEN cc.EndDate < CAST(GETDATE() AS DATE) THEN 'Expired'
        WHEN cc.EndDate >= CAST(GETDATE() AS DATE) THEN 'Active'
        ELSE 'Upcoming'
    END AS ContractStatus,
    DATEDIFF(DAY, cc.StartDate, ISNULL(cc.EndDate, CAST(GETDATE() AS DATE))) AS ContractDurationDays,
    cc.Status,
    cc.PriceListId,
    pl.PriceListCode,
    pl.PriceListName,
    COUNT(DISTINCT ci.ContractItemId) AS ItemCount,
    cc.CreatedAt
FROM dbo.CustomerContract cc
INNER JOIN dbo.Customer c ON cc.CustomerId = c.CustomerId
LEFT JOIN dbo.PriceList pl ON cc.PriceListId = pl.PriceListId
LEFT JOIN dbo.ContractItem ci ON cc.CustomerContractId = ci.CustomerContractId
GROUP BY 
    cc.CustomerContractId, cc.CustomerId, c.CustomerName, cc.ContractNumber,
    cc.ContractName, cc.StartDate, cc.EndDate, cc.Status, cc.PriceListId,
    pl.PriceListCode, pl.PriceListName, cc.CreatedAt;
GO
